App.register({group:'analytics',label:'09 / 经营分析',routes:[{path:'analytics/enterprise',title:'企业经营看板',icon:'▥',permission:'analytics',render(){const delivered=DB.projects.filter(p=>p.status==='已交付').length;return UI.page('BUSINESS INTELLIGENCE / ENTERPRISE','企业生产经营分析','以真实交付作品、作品质量、生产效率与 AI 成本为核心口径，不以任务数量简单考核。',UI.btn('导出经营摘要','audit:export','btn'),`<div class="grid grid-4">${UI.metric('正式交付作品',delivered+6,'全企业 · 本月','✓')}${UI.metric('交付集数','128','通过终审并归档','▤')}${UI.metric('平均质量评分','94.2','AI 质检 + 人工终审','✳')}${UI.metric('AI 生产成本','¥42,680','按模型调用与任务归集','￥')}</div><div class="grid grid-2 section-gap"><div class="card"><div class="card-head"><div><div class="card-title">月度作品交付</div><div class="card-sub">企业整体 · 正式交付口径</div></div>${UI.tag('近 7 周','blue')}</div>${UI.chart([25,38,43,55,61,72,88],['W1','W2','W3','W4','W5','W6','W7'])}</div><div class="card"><div class="card-title">租户生产贡献</div>${DB.tenants.filter(t=>t.status!=='已归档').map((t,i)=>`<div class="section-gap">${UI.progress([82,64,39][i],t.name)}</div>`).join('')}</div></div><div class="card section-gap"><div class="card-title">租户经营指标</div>${UI.table(['租户','项目数','交付作品','平均质量','AI 成本','预算使用'],DB.tenants.filter(t=>t.status!=='已归档').map((t,i)=>`<tr><td><b>${t.name}</b></td><td>${t.projects}</td><td>${[8,6,2][i]}</td><td>${[94.6,93.8,91.2][i]}</td><td class="mono">¥${t.used.toLocaleString()}</td><td>${t.budget?Math.round(t.used/t.budget*100):0}%</td></tr>`))}</div><div class="notice section-gap">经营统计按租户授权范围聚合；本页面为企业级管理视角。仅有汇总查看权限时，不会自动开放项目内容编辑。</div>`); }},{path:'analytics/employee',title:'员工产出分析',icon:'♙',permission:'analytics',render(){return UI.page('BUSINESS INTELLIGENCE / PEOPLE','员工产出与效率','从最终作品、交付集数、质量、周期和成本综合观察个人生产表现。', '',`<div class="grid grid-3">${UI.metric('统计员工','37','企业在册成员','♙')}${UI.metric('人均交付作品','3.4','本季度正式交付','▣')}${UI.metric('平均单集成本','¥286','按已交付作品核算','￥')}</div><div class="card section-gap"><div class="card-title">员工产出样例</div>${UI.table(['员工','所属租户','负责项目','交付作品','质量评分','AI 成本'],DB.users.filter(u=>u.status==='正常').map(u=>`<tr><td><b>${u.name}</b></td><td>${DB.tenants.find(t=>t.id===u.tenant)?.name||'—'}</td><td>${u.projects}</td><td>${u.delivered}</td><td>${u.delivered?['96.2','94.8','92.5','95.1'][u.projects%4]:'—'}</td><td class="mono">¥${u.cost.toLocaleString()}</td></tr>`))}</div><div class="notice section-gap">不以生成任务数、镜头数或素材数量代替作品产出；统计必须可追溯到正式交付记录。</div>`);}}]});
